using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SphotoApp.Web.Data; using SphotoApp.Web.Services; using SphotoApp.Web.ViewModels; namespace SphotoApp.Web.Controllers; [Authorize(Roles="Admin")] public class TemplateController(AppDbContext db,ITemplateService service):Controller { public async Task<IActionResult> Index()=>View(await db.ExcelTemplates.OrderByDescending(x=>x.CreatedAt).ToListAsync()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Upload(TemplateUploadVm m){if(!ModelState.IsValid)return RedirectToAction(nameof(Index));await service.UploadAsync(m.Name,m.File!,m.TargetSheetName,m.TargetStartRow);return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Activate(int id){await service.SetActiveAsync(id);return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){await service.DeleteAsync(id);return RedirectToAction(nameof(Index));} }
